import{z as s,x as i,o as e,c as l,q as B,j as t,D as a,d as n,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"框架的测试","description":"","frontmatter":{"title":"框架的测试","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-framework-testing.md","filePath":"quant/bf-framework-testing.md","lastUpdated":1791063341000}'),d={name:"quant/bf-framework-testing.md"};function D(p,E,h,F,u,C){const A=i("Mermaid");return e(),l("div",null,[E[2]||(E[2]=B('<h1 id="框架的测试" tabindex="-1">框架的测试 <a class="header-anchor" href="#框架的测试" aria-label="Permalink to &quot;框架的测试&quot;">​</a></h1><div class="epigraph"><p>对随机数据都赚钱的回测，先按框架缺陷立案，再谈策略。</p><footer>—— 据 Claessen and Hughes, QuickCheck: A Lightweight Tool for Random Testing of Haskell Programs, ICFP 2000 对性质测试的论述；对照 López de Prado, AFML, 2018 对泄漏的论述整理</footer></div><p><a href="/quant/bf-visual-diagnostics">上一课</a>把诊断做成面板；面板再全，也只能看见被算出来的东西。框架自身的正确性——账本守恒、重放确定、无前视、对拍一致——必须由站在策略之外的测试来守护：一次前视泄漏让夏普翻倍，一笔账本漂移把每笔成交差一分钱，攒起来就是一条假曲线。本课写回测框架的测试体系；它测的是引擎，不是策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>框架缺陷的麻烦在于它不抛异常，而是输出一条更好看的净值。四类惯犯。前视：信号在撮合前看见未到达的信息，<code>shift(1)</code> 不是充分防线，<a href="/quant/no-future-function">防止未来函数</a>列过完整清单。账本漂移：现金与仓位的更新在任何一条事件路径上不对称，差额小到日常看不出来。确定性破裂：只在并行、只在某顺序的回报下复现，单机重放永远正常。撮合乐观：默认值悄悄假设排队头、零延迟。四类都戴着 alpha 的面具，而统计调整（\\(N\\)、DSR）建立在「引擎量的是真相」的假设上——引擎坏了，全部试验的记账作废。</p><p><span class="marginnote">术语翻译：性质测试（property-based testing）就是「不写具体的输入输出样例，而是写一条永远该成立的性质，让机器随机生成成百上千组输入去攻击它」。例如「无论事件顺序多乱，成交量永远不超过剩余量」——框架自己找反例，找到后还会把触发条件自动缩到最小。</span></p><h3 id="测试的四个层次" tabindex="-1">测试的四个层次 <a class="header-anchor" href="#测试的四个层次" aria-label="Permalink to &quot;测试的四个层次&quot;">​</a></h3><p><strong>不变量层</strong>：账本守恒写成性质测试——权益等于现金加持仓市值；成交量永不超剩余量；无成交区间权益只随标记变动。性质测试对随机生成的事件序列断言这些关系，而不枚举样例。<strong>黄金重放层</strong>：构造答案解析已知的小场景——一笔已知价差与费用的往返、一个停牌日、一次竞价——输出存为黄金文件，重放必须逐字节一致。<strong>泄漏检测层</strong>：在随机游走合成数据上跑有费用的策略，期望净超额应 \\(\\le 0\\)；显著为正即引擎在漏信息。<strong>对拍层</strong>：同一数据同一假设下向量化与事件引擎的协议化对比（<a href="/quant/bf-vectorized-vs-event">向量化与事件驱动的取舍</a>），差异超阈值即失败。</p>',8)),(e(),t(o,null,{default:a(()=>[r(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E9%9A%8F%E6%9C%BA%E4%BA%8B%E4%BB%B6%E5%BA%8F%E5%88%97%E7%94%9F%E6%88%90%E5%99%A8%22%5D%20--%3E%20INV%7B%22%E8%B4%A6%E6%9C%AC%E4%B8%8D%E5%8F%98%E9%87%8F%E6%88%90%E7%AB%8B%3F%22%7D%0A%20%20INV%20--%3E%7C%E5%90%A6%7C%20SHR%5B%22%E7%BC%A9%E5%B0%8F%E7%9A%84%E5%8F%8D%E4%BE%8B%20%E4%BF%AE%E5%A4%8D%E5%BC%95%E6%93%8E%22%5D%0A%20%20INV%20--%3E%7C%E6%98%AF%7C%20GOLD%5B%22%E9%BB%84%E9%87%91%E5%9C%BA%E6%99%AF%E9%87%8D%E6%94%BE%20%E9%80%90%E5%AD%97%E8%8A%82%E6%AF%94%E5%AF%B9%22%5D%0A%20%20GOLD%20--%3E%20RW%7B%22%E9%9A%8F%E6%9C%BA%E6%B8%B8%E8%B5%B0%E4%B8%8A%E6%9C%89%E6%AD%A3%E5%87%80%E8%B6%85%E9%A2%9D%3F%22%7D%0A%20%20RW%20--%3E%7C%E6%98%AF%7C%20LEAK%5B%22%E6%8C%89%E6%B3%84%E6%BC%8F%E6%B8%85%E5%8D%95%E6%9F%A5%E5%BC%95%E6%93%8E%22%5D%0A%20%20RW%20--%3E%7C%E5%90%A6%7C%20PARA%7B%22%E6%8D%A2%E8%BF%9B%E7%A8%8B%E6%95%B0%E9%87%8D%E6%94%BE%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20PARA%20--%3E%7C%E5%90%A6%7C%20SEED%5B%22%E6%9F%A5%E7%A7%8D%E5%AD%90%E6%B5%81%E4%B8%8E%E5%BD%92%E5%B9%B6%E5%BA%8F%22%5D%0A%20%20PARA%20--%3E%7C%E6%98%AF%7C%20OK%5B%22%E8%BF%9B%E5%85%A5%E6%8C%81%E7%BB%AD%E9%9B%86%E6%88%90%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>性质测试的生成器要懂金融：生成的事件序列应包含人类容易忘记的顺序——确认未到先撤单、<code>pending_cancel</code> 状态下来成交、同一毫秒内乱序回报——这些正是<a href="/quant/order-state-machine">订单状态机</a>里最锋利的转移。QuickCheck 的方法在这里最值钱：失败时自动缩小成最小反例，一张「成交大于剩余量」的四步序列胜过一百条手写样例。网关替身按脚本注入延迟、拒单、部分成交、重复成交编号，验证坏消息下的行为与实盘状态机一致。持续集成的纪律：引擎改动必须重跑黄金场景加泄漏检测；套件小到每次提交都跑得完，大场景留给夜间。</p><p><span class="marginnote">数字实例：账本漂移可以小到荒谬又致命：某条事件路径上每笔成交因舍入多扣 0.01 元，一年 2500 笔也只差 25 元，对 100 万的净值是 0.0025%。但它破坏的是「权益=现金+持仓」这条恒等式——漂移的危害不在金额大小，而在恒等式不再成立后，所有对账失去裁判资格。</span></p><p><span class="marginnote">随机游走检测的阈值要诚实：有费用的策略在鞅上的净期望 \\(\\le 0\\)，但有限样本里夏普的抽样噪声大，把「显著为正」的门槛定在抽样分布的高分位（Lo, 2002 的提醒），否则测试会被噪声触发到人人麻木。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这套体系之所以分层，是因为四类缺陷各躲在不同的地方：不变量抓住状态层的任何不对称，黄金重放抓住语义回归；随机游走抓住信息层泄漏，因为它给引擎喂了「没有任何可赚的东西」；对拍抓住假设层的不一致。四层合起来覆盖的是<a href="/quant/bf-event-driven-anatomy">事件驱动框架的解剖</a>承诺的两样能力：可重放（黄金与确定性测试守护）与可替换（对拍与网关替身守护）。测试通过不等于模型正确——它只保证引擎量出来的东西值得被统计检验。</p><p>四类缺陷各躲在哪、由哪层测试来抓：</p>',7)),(e(),t(o,null,{default:a(()=>[r(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%3A%20%E7%BC%BA%E9%99%B7%E8%BA%B2%E5%9C%A8%E5%93%AA%2C%20%E8%B0%81%E6%9D%A5%E6%8A%93%3F%22%5D%20--%3E%20D1%5B%22%E5%89%8D%E8%A7%86%3A%20%E4%BF%A1%E5%8F%B7%E7%9C%8B%E8%A7%81%E6%9C%AA%E5%88%B0%E8%BE%BE%E4%BF%A1%E6%81%AF%22%5D%0A%20%20Q%20--%3E%20D2%5B%22%E8%B4%A6%E6%9C%AC%E6%BC%82%E7%A7%BB%3A%20%E6%9B%B4%E6%96%B0%E8%B7%AF%E5%BE%84%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%0A%20%20Q%20--%3E%20D3%5B%22%E7%A1%AE%E5%AE%9A%E6%80%A7%E7%A0%B4%E8%A3%82%3A%20%E5%B9%B6%E8%A1%8C%E4%B8%8B%E6%89%8D%E5%A4%8D%E7%8E%B0%22%5D%0A%20%20Q%20--%3E%20D4%5B%22%E6%92%AE%E5%90%88%E4%B9%90%E8%A7%82%3A%20%E6%8E%92%E9%98%9F%E5%A4%B4%E4%B8%8E%E9%9B%B6%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20D1%20--%3E%20T3%5B%22%E9%9A%8F%E6%9C%BA%E6%B8%B8%E8%B5%B0%E5%B1%82%3A%20%E6%97%A0%E4%BF%A1%E6%81%AF%E5%8D%B4%E8%B5%9A%E9%92%B1%E5%8D%B3%E6%B3%84%E6%BC%8F%22%5D%0A%20%20D2%20--%3E%20T1%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%E5%B1%82%3A%20%E6%9D%83%E7%9B%8A%20%3D%20%E7%8E%B0%E9%87%91%20%2B%20%E6%8C%81%E4%BB%93%22%5D%0A%20%20D3%20--%3E%20T4%5B%22%E5%AF%B9%E6%8B%8D%E4%B8%8E%E9%87%8D%E6%94%BE%3A%20%E6%8D%A2%E8%BF%9B%E7%A8%8B%E6%95%B0%E9%80%90%E5%AD%97%E8%8A%82%E4%B8%80%E8%87%B4%22%5D%0A%20%20D4%20--%3E%20T2%5B%22%E9%BB%84%E9%87%91%E5%9C%BA%E6%99%AF%3A%20%E5%B7%B2%E7%9F%A5%E4%BB%B7%E5%B7%AE%E8%B4%B9%E7%94%A8%E7%9A%84%E8%A7%A3%E6%9E%90%E7%AD%94%E6%A1%88%22%5D%0A%20%20T1%20--%3E%20OK%5B%22%E5%9B%9B%E5%B1%82%E9%80%9A%E8%BF%87%3A%20%E5%BC%95%E6%93%8E%E9%87%8F%E5%87%BA%E7%9A%84%E6%95%B0%E6%89%8D%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20T2%20--%3E%20OK%0A%20%20T3%20--%3E%20OK%0A%20%20T4%20--%3E%20OK%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>测试不能证明成交模型真实：模拟器与实盘的差距要靠<a href="/quant/slippage-attribution">滑点归因</a>对照实盘数据，测试只能守住「模拟器按声明的模型运行」。合成场景覆盖不了场所规则变更——规则是数据，随场所版本走，规则变更本身要有回归用例。性质测试的生成器自身是代码，也会有盲区，偶尔手工构造「奇怪的交易日」补足。最后，别把测试套件当成免检通道：过了测试的策略仍要走<a href="/quant/paper-to-live-staging">分级上线</a>的关卡，引擎正确只是入场券。</p><p><span class="marginnote">常见误区：初学者容易以为「测试全绿=回测可信」。四层测试只保证引擎按声明的模型运行——量尺没有坏；但量尺准不等于画的是真图：成交模型像不像真实市场要靠滑点归因对照实盘，统计显著性要另算。引擎正确只是入场券，不是通行证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引擎缺陷戴着 alpha 的面具；统计调整的前提是引擎量的是真相，测试守护这个前提。</li><li>四层：账本不变量的性质测试、黄金场景重放、随机游走泄漏检测、两层对拍。</li><li>生成器要覆盖罕见事件顺序；缩小反例是性质测试最值钱的产出。</li><li>确定性验收与并行一致：换进程数重放必须一致，先对事件流再谈容差。</li><li>测试保证引擎值得信任，不保证策略有效；晋级仍走模拟与分级上线关卡。</li><li>出处：Claessen and Hughes, <em>ICFP</em>, 2000；Lo, <em>Financial Analysts Journal</em>, 2002；López de Prado, <em>AFML</em>, 2018；站内<a href="/quant/no-future-function">防止未来函数</a>、<a href="/quant/order-state-machine">订单状态机</a>各课。</li></ul>',5))])}const c=s(d,[["render",D]]);export{m as __pageData,c as default};
